void qsort3(int *a,int l,int r){
    if(l>=r) return;
    int pivot=a[l],lt=l,i=l+1,gt=r;
    while(i<=gt){
        if(a[i]<pivot){int t=a[lt];a[lt]=a[i];a[i]=t;lt++;i++;}
        else if(a[i]>pivot){int t=a[i];a[i]=a[gt];a[gt]=t;gt--;}
        else i++;
    }
    qsort3(a,l,lt-1);
    qsort3(a,gt+1,r);
}

